def supports_subscribe(caps):
    return caps.get("resources", {}).get("subscribe") is True

def supports_list_changed(caps):
    return caps.get("resources", {}).get("listChanged") is True

# safely checking for a capability that might not exist yet
if client_caps.get("experimentalFeature"):
    enable_experimental_path()

def can_subscribe(server_capabilities):
    return server_capabilities.get("resources", {}).get("subscribe", False)

if can_subscribe(server_capabilities):
    client.subscribe(resource_uri)
else:
    client.read_once(resource_uri)  # graceful fallback, no error
